    "보충 학습 지도 · 소켓은 바이트를 전달합니다. 그 바이트의 의미와 보관 방법은 프로그램이 정합니다.": " Supplementary learning map · Sockets deliver bytes. Programs define their meaning and how to store them.",
    "원본의 제목과 쪽 번호": " The source title and page numbers",
    "제공된 PDF의 제목은 “TCP 소켓 시작하기”입니다. 이 장에서는 소켓 코드를 읽는 데 필요한 C 기초를 먼저 다룹니다.": " The provided PDF is titled “Getting Started with TCP Sockets.” This chapter first covers the C fundamentals needed to read socket code.",
    "PDF 한 쪽에는 슬라이드 두 장이 들어 있습니다. 본문의 “PDF 5쪽”은 파일의 다섯 번째 쪽이며, 슬라이드에 인쇄된 “10 / 60”과 다릅니다. 인쇄 번호가 건너뛰거나 반복되는 부분도 원본에 있습니다.": " Each PDF page contains two slides. “PDF p. 5” means the fifth page of the file, which differs from “10 / 60” printed on a slide. Some printed numbers skip or repeat in the source.",
    "데이터는 어디에 있을까?": " Where is the data?",
    "연속된 배열, 이름 붙인 필드, 주소를 따라가는 포인터를 이해합니다.": " Understand contiguous arrays, named fields, and pointers that follow addresses.",
    "연결하고, 되돌아오기.": " Link nodes and return.",
    "노드를 연결하는 방법과 마지막에 넣은 데이터를 먼저 꺼내는 LIFO 규칙을 배웁니다.": " Learn how to link nodes and follow the last-in, first-out (LIFO) rule.",
    "기다리고, 재사용하고, 찾기.": " Wait, reuse, and find.",
    "선형 큐의 한계를 원형 큐로 해결하고 해시 충돌을 추적합니다.": " Address the limits of linear queues with circular queues, then trace hash collisions.",
    "한 비트부터 수명까지.": " From one bit to lifetime.",
    "마스크로 값을 해석하고 할당한 메모리를 책임지고 해제합니다.": " Interpret values with masks and take responsibility for freeing allocated memory.",
    "본문과 전체 코드는 그대로 읽을 수 있습니다. 원리 도식은 모든 단계가 순서대로 표시됩니다. 단계 이동 버튼, 원형 큐 체험, 자동 복사와 완료 체크 저장에는 JavaScript가 필요합니다.": " The text and complete code remain readable. All diagram steps appear in order. Step controls, the circular queue exercise, automatic copying, and saved completion checks require JavaScript.",
    "원본 PDF 1–3쪽": " Source PDF pp. 1–3",
    "버퍼는 공간.": " A buffer provides space.",
    "길이는 별도의 정보.": " Length is separate information.",
    "쉬운 개념 설명": " The basic concept",
    "칸이 나란히 붙은 수납함": " A storage box with adjacent compartments",
    "같은 크기의 칸이 다섯 개 있는 수납함을 떠올려 보세요. 물건을 세 개 넣어도 수납함 자체는 여전히 다섯 칸입니다. 배열도 정해진 수의 원소를 나란히 보관하며, 각 칸을 0부터 시작하는 번호인": " Imagine five equally sized compartments. Even after placing objects in three of them, the box still has five compartments. An array likewise stores a fixed number of adjacent elements, located using a number starting at zero: the",
    "인덱스": " index",
    "로 찾습니다.": ".",
    "네트워크 버퍼에서는 “마련한 칸 수”와 “이번에 받은 데이터의 양”을 따로 기억합니다. 그림의 빈칸은 이번에 받은 데이터가 들어 있지 않은 구간입니다. 그곳의 메모리 값이 자동으로 0이 되었다는 뜻은 아닙니다.": " A network buffer tracks capacity and the amount received separately. The empty compartments in this picture lie outside the data received this time; their memory values have not automatically become zero.",
    "다섯 칸 수납함의 앞 세 칸에만 파란 구슬이 들어 있는 비유 그림": " An analogy showing blue marbles only in the first three of five compartments",
    "AI 생성 비유 그림 · 수납함 전체는 용량, 구슬이 들어 있는 구간은 유효 길이에 해당합니다.": " AI-generated analogy · The entire box represents capacity; the occupied section represents valid length.",
    "원리를 시각적으로 보기": " See how it works",
    "배열 원리의 단계별 도식": " Step-by-step array diagram",
    "공간을 먼저 준비합니다": " Prepare space first",
    "5바이트를 담을 공간을 준비했습니다. 아직 데이터를 받지 않았으므로 읽을 수신 데이터는 없습니다.": " Space for five bytes is ready. No data has arrived yet, so there is no received data to read.",
    "3바이트를 받았습니다": " Three bytes have arrived",
    "시작": " Start",
    "유효 구간 끝": " End of valid data",
    "recv()가 3을 반환했다고 가정합니다. 0~2번 칸에 16진수 41, 00, 42가 있고, 나머지 두 칸은 이번 수신 내용이 아닙니다.": " Assume recv() returned 3. Slots 0–2 contain hexadecimal 41, 00, 42. The other two slots are not part of this receive result.",
    "읽을 구간을 길이로 정합니다": " Use the length to choose what to read",
    "공간의 크기": " Capacity",
    "5바이트": " 5 bytes",
    "실제로 읽을 양": " Amount to read",
    "3바이트": " 3 bytes",
    "읽는 인덱스": " Indices read",
    "중간의 00도 정상 데이터입니다. 문자열의 끝으로 취급하지 않고, 세 바이트 모두 처리합니다.": " The middle 00 is valid data too. Process all three bytes instead of treating it as the end of a string.",
