    "논블로킹 소켓의": " On a nonblocking socket,",
    "은 지금 읽을 데이터가 없다는 뜻입니다. 읽을 수 있다는 알림을 받은 뒤 다시 시도합니다. 이 예제 함수의": " means no data is currently available. Retry after a readiness notification. This example function uses",
    "는 노드의 버퍼가 가득 찼다는 뜻입니다.": " to indicate that the node's buffer is full.",
    "이 함수가 맡는 범위": " What this function covers",
    "기존 서버의 수신 처리에 넣어 쓰는 함수 예시입니다. 단독 실행 프로그램은 아닙니다. 메시지 구분, 처리한 바이트 제거, 버퍼 확장, 연결 종료 후 노드 삭제는 호출하는 쪽에서 구현합니다.": " This is a function to integrate into an existing server's receive handling, not a standalone program. The caller implements message framing, removal of processed bytes, buffer growth, and node deletion after disconnection.",
    "블로킹 소켓은 데이터가 올 때까지 기다릴 수 있습니다. 목록 순서대로 읽으면 한 접속자를 기다리는 동안 다른 접속자 처리가 멈출 수 있습니다.": " A blocking socket may wait for data. Reading clients in list order can stall other clients while waiting for one.",
