    "맨 위 접시부터 꺼내는 접시 더미": " A stack of plates removed from the top",
    "접시를 차곡차곡 쌓으면 마지막에 올린 접시가 맨 위에 있습니다. 스택도 맨 위에서만 데이터를 넣고 꺼냅니다. 이 규칙을 LIFO라고 하며, “나중에 넣은 것을 먼저 꺼낸다”는 뜻입니다.": " The last plate placed on a stack sits on top. A stack likewise inserts and removes data only at the top. This is LIFO: last in, first out.",
    "데이터를 올리는 동작은 push, 꺼내는 동작은 pop입니다. 작업을 취소할 때 가장 최근에 저장한 상태부터 복원하는 경우에 유용합니다.": " Adding data is push; removing it is pop. This is useful for undoing work by restoring the most recently saved state first.",
    "흰 접시 두 장 위에 마지막으로 올린 파란 접시를 집어 올리는 모습": " A blue plate, added last, being lifted from two white plates",
    "AI 생성 비유 그림 · 위쪽 한 곳에서 넣고 꺼내는 순서에 주목하세요. 접시의 물리적 모양이 메모리 배치를 뜻하지는 않습니다.": " AI-generated analogy · Focus on insertion and removal at one end. The plates' physical shape does not describe memory layout.",
