    "10을 먼저 넣었지만 20을 먼저 꺼냈습니다. 실제 배열 안의 20을 지우지 않아도 count를 줄이면 유효 범위에서 제외됩니다.": " 10 was inserted first, but 20 was removed first. Decreasing count excludes 20 from the valid range without erasing its array storage.",
    "스택 이전 단계": " Previous stack step",
    "스택 다음 단계": " Next stack step",
    "보충 도식 · 두 값을 넣고 마지막 값을 먼저 꺼내는 과정을 순서대로 확인하세요. 인쇄에서는 모든 단계가 표시됩니다.": " Supplementary diagram · Push two values, then pop the most recent one. All steps appear when printed.",
    "배열을 쓰는 구현에서는 “현재 유효한 원소가 몇 개인가”만으로 맨 위 위치를 계산할 수 있습니다. 다음 예제는 count로 원소 수를 관리하고, 반환값으로 연산의 성공 여부를 알립니다. 덕분에 -1이라는 데이터도 빈 스택을 뜻하는 신호와 혼동하지 않고 다룰 수 있습니다.": " An array implementation can derive the top position from the valid element count. The example below manages count and returns operation success separately. This allows -1 to remain ordinary data instead of being confused with an empty-stack signal.",
    "스택은 LIFO입니다. 중첩된 괄호를 검사하거나 이전 작업 상태로 돌아갈 때 유용합니다. 함수가 호출되었다가 복귀하는 흐름도 이 원리와 연결됩니다.": " Stacks use LIFO. They help check nested parentheses or restore earlier work states. Function call and return flow follows a related principle.",
    "연산": " Operation",
    "아래 → 위": " Bottom → Top",
    "반환": " Return",
    "성공": " Success",
    "은 맨 위 원소의 인덱스를 기록하는 방식입니다. 보충 예제는 원소 수": " tracks the index of the top element. The supplementary example instead uses the element count,",
    "를 사용합니다. 비어 있으면 0, 꽉 차면 용량과 같습니다.": ". It is 0 when empty and equals capacity when full.",
    "top은 인덱스이고 count는 개수이므로, 같은 숫자라도 의미가 다릅니다. 예제를 읽을 때 어느 방식을 쓰는지 먼저 확인하세요.": " top is an index; count is a quantity. Even the same number has a different meaning, so first check which convention an example uses.",
    "Ubuntu · C17 / stack.c 발췌": " Ubuntu · C17 / Excerpt from stack.c",
    "데이터 -1과 실패 표시를 구분합니다": " Distinguish the data value -1 from failure",
