    "다운로드와 전체 코드": " Downloads and complete code",
    "각 파일은 독립 실행형입니다. HTML의 전체 코드와 다운로드 파일은 같은 내용입니다. 함수 이름이 반복되므로 여섯 소스를 한 실행 파일로 한꺼번에 링크하지 마세요.": " Each file is standalone. Complete code in the HTML matches the downloadable file. Function names repeat, so do not link all six sources into one executable.",
