    "전체 코드 펼치기 · port_table.c": " Expand complete code · port_table.c",
    "port_table.c 내려받기 ↗": " Download port_table.c ↗",
    "1장 에코 코드와 연결해서 읽기": " Connect this to Chapter 1's echo code",
    "1장의 에코 서버·클라이언트": " Chapter 1's echo server and client",
    "에서 받은 바이트 수를 확인하는 곳, 남은 데이터를 이어 보내는 반복문, EOF를 처리하고 자원을 정리하는 곳을 다시 찾아보세요.": " contain checks of received byte counts, loops for sending remaining data, and EOF handling and resource cleanup. Find these again.",
    "여기의": " Here,",
    "는 이미 배열에 담긴 헤더를 해석합니다. 실제 TCP에서는 나누어 도착한 헤더와 본문을 먼저 모아야 합니다. 여러 메시지가 한 번에 도착하면 각각 나누는 처리도 필요합니다.": " decodes a header already held in an array. Real TCP must first accumulate headers and bodies that arrive in pieces. It must also separate multiple messages received together.",
    "코드를 보기 전에,": " Before reading the code,",
    "결과부터 예측해 보기.": " predict the result.",
    "1,024바이트 배열에 recv()가 37을 반환했다면 어디까지 읽을까요?": " If recv() returns 37 for a 1,024-byte array, how far should you read?",
    "0번부터 36번까지, 총 37바이트입니다. 배열 자체에 적용한 sizeof는 전체 용량을 알려 줍니다. 이번에 받은 길이는 recv()의 반환값으로 확인합니다.": " Read indices 0–36: 37 bytes total. sizeof applied to the array itself gives capacity. recv()'s return value gives the amount received this time.",
    "구조체를 packed로 만들면 바로 전송해도 될까요?": " Can a packed structure be sent directly?",
    "패딩 외에도 엔디언·필드 형식·정렬·객체 접근 규칙을 확인해야 합니다. 학습용 코드에서는 규격대로 바이트를 조립해 직렬화합니다.": " Besides padding, check endianness, field format, alignment, and object-access rules. The teaching code explicitly assembles bytes according to the format.",
    "포인터가 NULL이 아니면 안전한가요?": " Is a non-NULL pointer safe?",
    "아닙니다. 객체 수명, 범위, 타입, 정렬을 확인해야 합니다. 유효하지 않은 포인터도 NULL이 아닐 수 있습니다.": " Not necessarily. Check lifetime, bounds, type, and alignment. An invalid pointer can also be non-NULL.",
    "새 노드를 head에 넣을 때 어떤 대입이 먼저일까요?": " Which assignment comes first when inserting at head?",
    "새 노드의 next가 기존 head를 가리키게 한 뒤 head를 새 노드로 바꿉니다. 기존 목록으로 가는 연결을 보존해야 합니다.": " Point the new node's next to the old head, then change head to the new node. Preserve the link to the existing list.",
    "-1이 정상 데이터라면 빈 스택은 어떻게 알까요?": " If -1 is valid data, how do you detect an empty stack?",
    "성공 여부는 bool 반환값으로, 데이터는 out 포인터로 전달합니다. 값과 상태를 분리하면 -1도 저장할 수 있습니다.": " Return success as bool and deliver data through an out pointer. Separating data and status allows -1 to be stored normally.",
    "선형 큐에서 front=3, rear=5, 용량 5이면 왜 삽입이 실패할까요?": " Why does a linear queue with front=3, rear=5, capacity 5 reject insertion?",
    "이 구현은 rear를 뒤로만 이동하므로 다음 삽입 위치가 배열 밖입니다. 앞의 빈 세 칸을 재사용하는 규칙이 없습니다.": " This implementation only advances rear, so its next insertion is outside the array. It has no rule for reusing the three empty front slots.",
    "5칸 원형 큐의 front=2, rear=4에서 E를 넣으면 어떻게 될까요?": " What happens when E is inserted with front=2, rear=4 in a five-slot circular queue?",
    "E를 index 4에 저장하고 rear를 0으로 바꿉니다. 곧바로 index 0에 저장하는 것이 아닙니다.": " Store E at index 4, then change rear to 0. Do not immediately store E at index 0.",
    "80과 8080이 같은 버킷에 있으면 같은 키일까요?": " If 80 and 8080 share a bucket, are they the same key?",
    "아닙니다. 버킷 내부의 체인을 탐색하며 원래 port 값을 비교해야 합니다.": " No. Traverse the bucket's chain and compare the original port values.",
    "0x12에서 SYN을 끄고 ACK를 유지하면 어떤 값일까요?": " What remains after clearing SYN in 0x12 while preserving ACK?",
    "0x12 & ~0x02 = 0x10입니다. SYN은 bit 1, ACK는 bit 4입니다.": " 0x12 & ~0x02 = 0x10. SYN is bit 1 and ACK is bit 4.",
    "free(p); p = NULL; 뒤에 같은 주소를 가진 q도 안전할까요?": " After free(p); p = NULL;, is q with the same address safe?",
    "아닙니다. q도 해제된 영역을 가리키므로 더 이상 그 메모리에 접근하는 데 사용할 수 없습니다. p에 NULL을 대입해도 q까지 바뀌지는 않습니다.": " No. q also refers to freed storage and cannot be used to access it. Assigning NULL to p does not change q.",
    "원본 PDF 1–22쪽 전체": " Entire source PDF, pp. 1–22",
    "원본의 본문·표·메모리 도식·코드 화면을 확인해 설명을 재구성했습니다. 배열부터 메모리 관리까지 10개 주제를 도식과 실행 코드로 설명합니다. 본문의 “보충·보완”과 실행 예제는 새로 작성한 내용입니다.": " Explanations were reconstructed after reviewing the source text, tables, memory diagrams, and code screenshots. Diagrams and runnable code cover ten topics from arrays to memory management. Supplements, corrections, and runnable examples were newly written.",
    "전체 강의 목록 →": " All lectures →",
    "슬라이드의 인쇄 번호는 01/60부터 58/60까지 불연속적으로 나타나며, 일부 실습 슬라이드에는 35/60이 반복됩니다. 빠진 번호를 임의로 복원하지 않았습니다. PDF 13쪽의 중복 함수·빈칸, 16·18·20·22쪽의 빈칸은 실행 예제에서 보완했습니다. 일부 PDF 텍스트층과 실제 그림의 내용이 달라, 시각자료를 함께 확인했습니다.": " Printed slide numbers run discontinuously from 01/60 through 58/60; some exercises repeat 35/60. Missing numbers were not invented. Duplicate functions and blanks on PDF p. 13 and blanks on pp. 16, 18, 20, and 22 were completed in the runnable examples. Visuals were checked because some PDF text layers differ from the actual pictures.",
