    "통신에 필요한 상태와 자원을 관리합니다.": " Manages communication state and resources.",
    "개념 도식 · 변수에는 소켓 자원 자체가 아니라, 이후 함수에 전달할 식별자가 들어갑니다.": " Concept diagram · The variable holds an identifier for later calls, not the socket resource itself.",
    "은 소켓을 만들고 식별자를 반환합니다. Windows에서는 이를": " creates a socket and returns an identifier. Windows stores it in",
