    "TCP 통신에서는 소켓 생성 뒤에 주소 설정, 연결 또는 연결 수락, 송수신이 이어집니다. 이번 프로그램은 이 중": " TCP normally continues from socket creation to address setup, connection or acceptance, and data exchange. This program performs only",
