    "02 / 프로그램 구조": " 02 / PROGRAM STRUCTURE",
    "원본 PDF 3, 13, 21, 26–28쪽": " Source PDF pp. 3, 13, 21, 26–28",
    "정상 흐름을 먼저 읽고, 실패하는 지점을 찾습니다": " Read the success path, then locate possible failures",
    "두 운영체제 모두 소켓을 생성하고 사용이 끝나면 닫습니다. Windows에서는 그 앞뒤에 Winsock 사용을 시작하고 끝내는 단계가 추가됩니다. 아래는 모든 호출이 성공했을 때의 실행 순서입니다.": " Both operating systems create a socket and close it when finished. Windows adds steps before and after to begin and end Winsock use. The sequence below assumes every call succeeds.",
    "Winsock 사용 준비": " Prepare Winsock",
    "Winsock 사용 종료": " Finish Winsock use",
    "실행 순서 · 실제 송수신 코드는 소켓 생성과 닫기 사이에 들어갑니다. 이번 예제는 생성 직후 소켓을 닫습니다.": " Execution order · Real send/receive code belongs between creation and closing. This example closes the socket immediately after creation.",
    "오류 처리는 이 흐름의 각 호출 직후에 들어갑니다. 초기화가 실패하면 소켓을 만들 수 없고, 생성이 실패하면 닫을 소켓이 없습니다. 따라서": " Error handling follows each call. Failed initialization prevents socket creation, and failed creation leaves no socket to close. Therefore,",
    "반환값을 확인한 뒤 다음 단계로 이동": " check the return value before proceeding",
    "해야 합니다.": ".",
    "프로그램의 실행 순서": " Program execution order",
    "에서 준비 → 생성 → 정리를 수행합니다. 실패한 경우에는 오류를 출력하고, 확보한 자원을 정리한 뒤 종료합니다.": " performs preparation → creation → cleanup. On failure, it reports the error, releases acquired resources, and exits.",
    "소스 파일의 작성 순서": " Source-file order",
    "헤더 포함 → 보조 함수 정의 →": " Include headers → Define helpers →",
    "순서로 배치합니다. 파일에서 먼저 보이는 보조 함수가 자동으로 먼저 실행되는 것은 아닙니다.": ". A helper appearing first in the file does not automatically execute first.",
    "03 / 사용 준비": " 03 / PREPARATION",
    "원본 PDF 13–20, 27쪽": " Source PDF pp. 13–20, 27",
    "Windows에서는 Winsock을 먼저 초기화합니다": " Initialize Winsock first on Windows",
    "은 Windows의 소켓 API입니다.": " is the Windows socket API.",
    "은 사용할 버전을 요청하고 초기화 결과를 구조체에 기록합니다. Linux의 기본 소켓 API에는 이 초기화 단계가 없습니다.": " requests a version and records initialization information in a structure. Basic Linux socket APIs do not require this initialization step.",
