    "로 전달한 공간에 초기화 정보 기록": " Initialization information written to the supplied storage",
    "값의 전달 · 반환값은 성공 여부를, 구조체는 사용하기로 한 버전 등의 정보를 전달합니다.": " Passing results · The return value indicates success; the structure contains information such as the negotiated version.",
