    "는 그 변수의 주소이므로, 함수가 호출한 쪽의 구조체에 결과를 쓸 수 있습니다.": " is its address, allowing the function to write into the caller's structure.",
    "는 하위 바이트에 주 버전, 상위 바이트에 부 버전을 넣습니다.": " places the major version in the low byte and the minor version in the high byte.",
    "초기화 성공 후": " After successful initialization,",
    "으로 합의된 버전의 두 부분을 읽습니다. 아래 전체 코드는 두 값이 2인지 확인한 뒤 소켓을 만듭니다. 버전이 맞지 않아 중단하더라도 성공한 초기화는 정리해야 합니다.": " read the two parts of the negotiated version. The complete code checks that both are 2 before creating a socket. Successful initialization still needs cleanup even if a version mismatch stops the program.",
