    "인자 해석 · 이 조합은 IPv4 TCP 소켓을 생성합니다. 0은 “프로토콜 없음”을 뜻하지 않습니다.": " Argument interpretation · This combination creates an IPv4 TCP socket. 0 does not mean “no protocol.”",
