    "또는": " or",
    "TCP는 연결을 맺은 뒤 순서 있는 바이트 스트림을 전달합니다. UDP는 데이터그램 단위를 유지하지만 도착·순서·중복 방지를 보장하지 않습니다. IPv4와 IPv6는 주소 체계이고, TCP와 UDP는 전송 프로토콜이므로 서로 다른 선택입니다.": " TCP establishes a connection and delivers an ordered byte stream. UDP preserves datagrams but does not guarantee arrival, order, or duplicate prevention. IPv4/IPv6 select the address family; TCP/UDP select the transport protocol.",
