    "0 이상의 fd": " Nonnegative fd",
    "함수마다 실패를 알리는 규약이 다릅니다. 원본은 이를 오류 확인이 필요 없는 함수, 반환값 자체가 오류 코드인 함수, 반환값과 별도 오류 코드를 함께 확인하는 함수로 분류합니다. 이 장에서는 위 표에 나온 함수들의 규약을 기준으로 작성합니다.": " Functions use different failure conventions. The source classifies functions as requiring no error check, returning an error code directly, or requiring both a return-value check and a separate error code. Follow the conventions in the table for this chapter's functions.",
