    "에 프로그램의 최종 성공·실패를 기록합니다. 초기화가 성공한 뒤 오류가 생기면": ". If an error occurs after successful initialization, it changes the value to",
    "로 바꾸고 공통 정리 지점까지 진행합니다. 이렇게 하면 중간에서 바로 종료해 정리를 빠뜨리는 일을 줄일 수 있습니다.": " and continues to common cleanup. This helps avoid skipping cleanup by exiting early.",
    "이번 예제는 기본 블로킹 소켓을 생성한 뒤 바로 닫습니다. 연결된 소켓의 남은 데이터, 논블로킹 동작, linger 설정은 이후 통신 단계에서 다룹니다. 닫은 식별자는 이전 소켓을 가리키는 값으로 다시 사용하지 않습니다.": " This example creates a basic blocking socket and immediately closes it. Pending data on connected sockets, nonblocking behavior, and linger settings are later topics. Do not reuse a closed identifier as though it still referred to its old socket.",
    "실패 위치에 따라 닫을 자원을 구분할 수 있습니다.": " I can identify which resources to release at each failure point.",
