    "는 전처리·컴파일·어셈블을 거쳐 오브젝트를 만들고 링크 전에 멈춥니다. 다음 링크 명령에서 실행 파일을 만듭니다.": " performs preprocessing, compilation, and assembly to create an object, then stops before linking. The next link command creates an executable.",
    "컴파일할 때:": " During compilation:",
    "로 함수 선언과 타입을 읽습니다. 컴파일러가 함수의 인자와 반환값을 확인하는 데 필요한 정보입니다.": " reads function declarations and types, allowing the compiler to check arguments and return values.",
    "링크할 때:": " During linking:",
    "MinGW의": " MinGW's",
    "로 Winsock 라이브러리를 지정합니다. 헤더를 포함하는 것과 라이브러리를 연결하는 것은 별도 단계입니다.": " selects the Winsock library. Including headers and linking libraries are separate steps.",
    "실행할 때:": " During execution:",
