    "를 선택합니다. Ubuntu 터미널에서 C17로 빌드합니다.": " is the Ubuntu choice. Build it as C17 in an Ubuntu terminal.",
    "Windows: Dev-C++에서 빌드하고 실행하기": " Windows: build and run in Dev-C++",
    "를 별도 실습 폴더에 내려받습니다. 이 파일은 UTF-8입니다. 한글 주석이 깨지면 편집기의 파일 인코딩 설정을 확인합니다.": " should be downloaded into a separate practice folder. It is UTF-8; check the editor's encoding if Korean comments appear corrupted.",
