    "완료 체크": " Completion checklist",
    "WSL은 Windows에서 리눅스 환경을 실행하는 기능입니다. Ubuntu는 여기에 설치할 리눅스 배포판이며, GCC는 Ubuntu 안에서 사용할 컴파일러입니다.": " WSL runs a Linux environment on Windows. Ubuntu is the Linux distribution installed in it, and GCC is the compiler used inside Ubuntu.",
    "Windows 11 PC, 인터넷 연결, Windows 관리자 권한을 준비합니다.": " Prepare a Windows 11 PC, Internet access, and Windows administrator permissions.",
    "진행 중인 작업을 저장합니다. 설치 중 재부팅이 필요할 수 있습니다.": " Save your work. Installation may require a restart.",
    "작업 관리자 → 성능 → CPU에서": " In Task Manager → Performance → CPU, check",
    "가상화: 사용": " Virtualization: Enabled",
    "여부를 확인합니다. 꺼져 있다면 PC 제조사의 BIOS/UEFI 안내를 확인하세요.": ". If disabled, consult your PC manufacturer's BIOS/UEFI instructions.",
    "WSL 설치·업데이트·상태 확인에 사용합니다. 시작 메뉴에서 PowerShell을 검색하세요.": " Use this for WSL installation, updates, and status checks. Find PowerShell in the Start menu.",
    "Ubuntu 터미널 / Bash": " Ubuntu terminal / Bash",
    "패키지 설치·파일 작업·GCC 컴파일에 사용합니다. 시작 메뉴에서 Ubuntu를 실행하세요.": " Use this for package installation, file operations, and GCC compilation. Launch Ubuntu from the Start menu.",
    "명령어는 한 줄씩 실행하고 결과를 확인하세요. 코드 블록에는": " Run one command at a time and inspect its result. Code blocks omit prompts such as",
    "같은 프롬프트를 넣지 않았으므로 그대로 복사할 수 있습니다.": " so commands can be copied directly.",
    "WSL 2와 Ubuntu 설치": " Install WSL 2 and Ubuntu",
    "이미 Ubuntu를 설치했다면": " If Ubuntu is already installed, use the",
    "Ubuntu 실행 가이드": " Ubuntu launch guide",
    "에서 배포판을 확인하고 바로 실행하세요.": " to identify and start the distribution.",
    "교수님 추천 자료인": " This follows the instructor-recommended",
    "위키독스 「2.2. WSL 설치와 실행」": " Wikidocs “2.2. Installing and Running WSL”",
    "의 배포판 설치·계정 생성 흐름을 따릅니다. 아래는 자료의 예시인": " sequence for distribution installation and account creation. The example below uses",
    "기준이며, 수업에서 지정한 버전이 있으면 그 버전을 우선하세요.": " from that material. Prefer any version specifically required by your course.",
    "① 먼저 설치 상태 확인": "① Check the current installation first",
    "WSL 설치와 Ubuntu 설치는 별개입니다.": " Installing WSL and installing Ubuntu are separate tasks.",
    "WSL 버전이 출력되어도": " Even if WSL prints its version, if",
    "에서 “설치된 배포가 없습니다”가 나오면 현재 Windows 계정에 등록된 리눅스가 없는 상태입니다.": " says no distributions are installed, no Linux distribution is registered for the current Windows account.",
    "“기본 버전: 2”만으로 Ubuntu 설치가 확인되는 것은 아닙니다. 배포판이 없다면 다음 설치 단계로 진행하세요.": "“Default Version: 2” alone does not confirm that Ubuntu is installed. If no distribution exists, proceed to installation.",
    "② 설치할 배포판 선택": "② Select a distribution to install",
    "시작 메뉴에서 PowerShell을 검색해": " Search for PowerShell in the Start menu and choose",
    "관리자 권한으로 실행": " Run as administrator",
    "합니다. 먼저 온라인 목록에 원하는 배포판 이름이 있는지 확인하세요.": ". First check that the desired distribution name appears in the online list.",
    "Windows PowerShell · 관리자": " Windows PowerShell · Administrator",
    "Ubuntu가 아직 설치되지 않았다면 아래 명령을 실행합니다. 이미 수업에 맞는 Ubuntu가 등록되어 있다면 중복 설치하지 않고 해당 배포판을 사용하면 됩니다.": " If Ubuntu is not installed, run the command below. If a course-compatible Ubuntu is already registered, use it rather than installing another copy.",
    "재부팅 안내가 나오면 작업을 저장하고 Windows를 재부팅합니다. 이후 시작 메뉴에서 Ubuntu 22.04를 열거나 아래 명령으로 실행하고, STEP 03의 사용자 계정을 만듭니다.": " If prompted to restart, save your work and restart Windows. Then open Ubuntu 22.04 from Start or use the command below, and create the user account in STEP 03.",
    "추천 자료는 Windows 기능 활성화와 Store 설치를 나누어 설명합니다. 이미 WSL 버전이 정상 출력되는 환경에서는 배포판 설치부터 진행할 수 있습니다.": " The recommended material separates enabling Windows features from Store installation. If WSL already reports its version correctly, you can begin with distribution installation.",
    "최신 WSL의 커널은 WSL 업데이트로 관리하므로 별도의 구형 커널 패키지 설치부터 시작할 필요는 없습니다.": " Current WSL kernels are managed through WSL updates; starting with a separate old kernel package is unnecessary.",
    "WSL 2 사용 여부 확인": " Check whether WSL 2 is in use",
    "목록에서": " In the list, check that",
    "Ubuntu-22.04 행의 VERSION이 2": " the Ubuntu-22.04 row has VERSION 2",
    "는 종료된 상태라는 뜻이며 오류가 아닙니다.": " means stopped, not an error.",
    "나": " or",
    "처럼 다른 이름이 표시되면 이후 명령의": " may appear as the registered name. In later commands, replace",
    "자리에 실제 등록된 이름을 사용하세요.": " with that actual name.",
    "VERSION이 1인 경우에만 다음 명령을 실행합니다. 기존 배포판에 중요한 파일이 있다면 먼저 백업하세요.": " Run the next command only if VERSION is 1. Back up important files in an existing distribution first.",
    "Windows PowerShell · 필요한 경우": " Windows PowerShell · If needed",
    "설치 및 WSL 버전 확인:": " Installation and WSL version checks:",
    "Microsoft WSL 설치 문서": " Microsoft WSL installation documentation",
    "WSL 1·2에서 Ubuntu 실행하기": " Launch Ubuntu on WSL 1 or 2",
    "설치한 Ubuntu를 처음 열거나, PC를 재시작한 뒤 다시 실습할 때 사용하는 순서입니다. 여기서 실행하는 것은 명령어를 입력하는": " Use these steps when opening Ubuntu for the first time or resuming after a PC restart. They open the command-line",
    "Ubuntu 터미널(Bash)": " Ubuntu terminal (Bash)",
    "입니다. Ubuntu 바탕화면 전체가 열리는 것은 아닙니다.": ", not a complete Ubuntu desktop.",
    "WSL 1과 WSL 2의 Ubuntu 실행 명령은 같습니다.": " The launch command is the same for WSL 1 and WSL 2.",
    "WSL은 실행 환경의 이름이고, 1·2는 배포판에 적용된 실행 방식입니다.": " WSL names the environment; 1 and 2 are execution modes assigned to each distribution.",
    "별도의": " There is no separate",
    "명령을 찾을 필요 없이": " command to find. Use",
    "을 사용합니다. 이 가이드의 실습 기준은 WSL 2입니다.": ". This guide's practice targets WSL 2.",
    "① PowerShell에서 설치된 Ubuntu 이름 확인": "① Check the installed Ubuntu name in PowerShell",
    "Windows 시작 메뉴에서": " From the Windows Start menu, open",
    "을 열고 아래 명령을 한 줄씩 실행합니다. 일반적인 Ubuntu 실행에는 관리자 권한이 필요하지 않습니다.": " and run the commands one by one. Ordinary Ubuntu startup does not require administrator permissions.",
    "은 WSL 구성 요소 버전,": " shows WSL component versions;",
