    "은 자신의 루프백 주소,": " is the loopback address;",
    "은 포트입니다. 종료는": " is the port. To exit, use",
    "외부 PC와 연결하는 구성은 WSL 네트워크 모드와 방화벽에 따라 별도 설정이 필요합니다.": " Connections from external PCs require separate configuration depending on WSL networking mode and firewall settings.",
    "막혔을 때 확인할 것": " When you get stuck",
    "Ubuntu 실행 시 지정한 이름의 배포판이 없다고 나와요": " Ubuntu says no distribution with that name exists",
    "PowerShell에서": " In PowerShell, run",
    "를 실행하고 NAME 열의 이름을 그대로 사용하세요. 예를 들어 이름이": " and use the exact NAME-column value. For example, if it is",
    "이면": ", use",
    "로 엽니다.": " to open it.",
    "설치 가능한 배포판을 보여 주는": " The installable-distribution list shown by",
    "과 이미 설치된 배포판 목록은 다릅니다.": " is different from the installed-distribution list.",
    "에서 확인 순서를 볼 수 있습니다.": " shows the checking sequence.",
    "wsl -l -v에 “설치된 배포가 없습니다”가 나와요": " wsl -l -v says no distributions are installed",
    "WSL 실행 파일은 있지만 현재 Windows 계정에 배포판이 등록되지 않은 상태입니다.": " The WSL executable exists, but no distribution is registered for this Windows account.",
    "에서 온라인 목록을 확인한 후 Ubuntu를 설치하고 최초 계정 설정을 마치세요. 다른 Windows 계정에서 설치했다면 현재 계정의 목록에는 나타나지 않을 수 있습니다.": " shows how to check the online list, install Ubuntu, and complete first-time account setup. A distribution installed under another Windows account may be absent from the current account's list.",
    "WSL1이 지원되지 않는다는 메시지가 나와요": " A message says WSL 1 is unsupported",
    "WSL 2를 사용할 때 WSL1 지원 안내만으로 실패라고 판단하지 않습니다.": " When using WSL 2, a WSL 1 support notice alone does not indicate failure.",
    "에 Ubuntu 행과 VERSION 2가 표시되는지, 해당 Ubuntu를 실제로 실행할 수 있는지 확인하세요.": " should show an Ubuntu row with VERSION 2; also check that the distribution actually launches.",
    "sudo가 비활성화되어 있거나 비밀번호가 틀리다고 나와요": " sudo is disabled or says the password is wrong",
    "PowerShell의 Windows용 sudo가 아닌 Ubuntu 안의 sudo를 사용해야 합니다. PowerShell에서": " Use sudo inside Ubuntu, not Windows sudo in PowerShell. From PowerShell, enter with",
    "로 들어간 다음": ", then run",
    "를 실행하세요.": ".",
    "비밀번호는 Windows PIN이 아니라 Ubuntu 계정 생성 때 정한 비밀번호입니다. 입력 중 글자가 보이지 않는 것은 정상입니다.": " The password is the one set when creating the Ubuntu account, not your Windows PIN. No visible characters during password entry is normal.",
    "WSL 설치가 0%에서 멈추거나 도움말만 나와요": " WSL installation remains at 0% or only displays help",
    "PowerShell에서 배포판 목록을 확인하고 웹 다운로드 방식으로 다시 시도합니다.": " Check the distribution list in PowerShell and retry using web download.",
    "가상화 관련 오류로 Ubuntu가 시작되지 않아요": " Ubuntu fails to start with a virtualization error",
    "설치 후 재부팅했는지, 작업 관리자에서 CPU 가상화가 활성화되어 있는지 확인합니다. BIOS/UEFI에서 Intel VT-x 또는 AMD-V/SVM 설정은 제조사 안내를 따르세요. 오류가 계속되면": " Check that Windows was restarted after installation and CPU virtualization is enabled in Task Manager. Follow the manufacturer's instructions for Intel VT-x or AMD-V/SVM in BIOS/UEFI. If errors persist, consult",
    "Microsoft 문제 해결 문서": " Microsoft troubleshooting documentation",
    "에서 오류 코드를 확인하세요.": " for the error code.",
    "gcc: command not found가 나와요": " gcc: command not found",
    "Ubuntu 터미널인지 먼저 확인하고": " First confirm that this is an Ubuntu terminal, then run",
    "을 실행하세요. 설치가 성공했는지 확인한 뒤": ". After confirming successful installation, use",
    "로 경로를 조회합니다.": " to locate it.",
    "hello.c: No such file or directory가 나와요": " hello.c: No such file or directory",
    "로 위치와 파일명을 확인하세요.": " checks the current location and filename.",
    "로 이동하고, 파일이": " moves to the work folder. Check that the file was not accidentally saved as",
    "로 저장되지 않았는지 확인합니다.": ".",
    "./hello 실행이 안 되거나 Permission denied가 나와요": "./hello fails to run or reports Permission denied",
    "먼저 GCC 컴파일이 오류 없이 끝났는지 확인합니다. 이 가이드처럼 Ubuntu 홈 폴더에서 다시 빌드하세요. 스크립트는 실행 권한이 필요할 수 있지만, 직접 GCC로 만든 실행 파일은 보통 권한이 자동 부여됩니다. 컴파일할 때 sudo를 붙일 필요는 없습니다.": " First check that GCC finished without errors. Rebuild under Ubuntu's home folder as in this guide. Scripts may need executable permissions, but GCC-generated executables normally receive them automatically. Compilation does not require sudo.",
    "code: command not found가 나와요": " code: command not found",
    "Windows에 VS Code가 설치되어 있고 설치 옵션의 PATH 추가가 적용됐는지 확인한 뒤 Ubuntu 터미널을 다시 여세요. Windows VS Code에서 F1 →": " Check that VS Code is installed on Windows and its Add to PATH option took effect, then reopen Ubuntu. You can also connect from Windows VS Code using F1 →",
    "로 연결하는 방법도 있습니다.": ".",
    "WSL을 업데이트하거나 다시 시작하고 싶어요": " I want to update or restart WSL",
    "작업을 저장한 뒤 아래 명령을 PowerShell에서 실행하세요. shutdown은 모든 WSL 배포판과 실행 중인 프로세스를 종료합니다.": " Save your work, then run the following in PowerShell. shutdown stops all WSL distributions and their running processes.",
