    "기존 C 소스와 CP949 인코딩을 보존한 기록입니다. LinkedList.c와 main.c는 요청에 따라 제외했습니다.": " These records preserve the original C sources and CP949 encoding. LinkedList.c and main.c were excluded as requested.",
    "콘솔 출력은 검증 당시 소스의 main() 실행 결과입니다. Linux 검증 범위와 전체 로그는 환경 설정 보고서에서 확인할 수 있습니다.": " Console output comes from main() in the sources at the time of verification. See the environment report for Linux verification scope and complete logs.",
    "브라우저 저장소를 사용할 수 없어 체크는 현재 페이지를 열어 둔 동안만 유지됩니다.": " Browser storage is unavailable. Checks remain only while this page stays open.",
    "저장이 제한되어 체크는 현재 페이지를 열어 둔 동안만 유지됩니다.": " Storage is restricted. Checks remain only while this page stays open.",
    "코드를 복사했습니다.": " Code copied.",
    "자동 복사가 제한되어 코드를 선택했습니다. Ctrl+C 또는 복사 메뉴를 이용하세요.": " Automatic copying is restricted, so the code has been selected. Use Ctrl+C or the Copy menu.",
    "TCP는 ABCDEFGHI의 순서를 유지하지만 수신 호출의 분할 방식은 달라질 수 있습니다. 수신한 바이트를 누적하고 응용 프로토콜로 메시지 경계를 복원합니다. 개념 시뮬레이션입니다.": " TCP preserves the order ABCDEFGHI, but receive calls may split it differently. Accumulate received bytes and recover message boundaries using the application protocol. This is a concept simulation.",
    "유실 예: DEF가 도착하지 않아 ABC와 GHI만 받았습니다. 도착한 각 데이터그램의 경계는 유지됩니다. UDP 자체는 유실된 DEF를 재전송하지 않습니다. 개념 시뮬레이션입니다.": " Loss example: DEF did not arrive, so only ABC and GHI were received. Each arrived datagram retains its boundary. UDP itself does not retransmit the missing DEF. This is a concept simulation.",
    "정상 도착 예: 각 데이터그램 ABC, DEF, GHI를 별도로 받습니다. 이 순서는 항상 보장되지 않으며 유실·중복도 가능합니다. 개념 시뮬레이션입니다.": " Arrival example: ABC, DEF, and GHI are received as separate datagrams. This order is not guaranteed; loss and duplicates are also possible. This is a concept simulation.",
    "정상 도착 예시 보기 ↻": " Show normal arrival example ↻",
    "데이터그램 유실 예시 보기 ↻": " Show datagram loss example ↻",
