    "강의 자료의 제목과 참고한 PDF 쪽 번호를 적으세요. 슬라이드에 인쇄된 번호가 다르면 함께 표기합니다. 공식 문서는 해당 설명을 확인할 수 있는 페이지로 연결합니다.": " State the lecture title and referenced PDF pages. Include printed slide numbers if they differ. Link official documentation directly to the supporting page.",
    "작성 안내": " Authoring guidance",
    "· 원본 PDF와 추출 슬라이드는 로컬 자료로 보관합니다. 본문에는 원본 뷰어나 다운로드 링크 대신 개념 설명과 HTML 도식을 넣습니다. 보충 설명과 실습 예제는 원본 내용과 구분하세요.": "· Preserve source PDFs and extracted slides locally. Present concepts through explanations and HTML diagrams in the text. Distinguish supplementary explanations and practice examples from the source.",
