    "<p class=\"noscript\">JavaScript가 꺼져 있어도 본문과 실습 코드를 읽을 수 있습니다. 목차 접기·체험·완료 저장·복사 버튼은 JavaScript가 필요합니다. 인쇄는 브라우저의 Ctrl+P를 이용하세요.</p>": "<p class=\"noscript\">You can read the text and practice code with JavaScript disabled. Collapsing the contents, interactive exercises, saved checks, and copy buttons require JavaScript. Use the browser's Ctrl+P to print.</p>",
    "<p class=\"noscript\">본문과 전체 코드는 그대로 읽을 수 있습니다. 원리 도식은 모든 단계가 순서대로 표시됩니다. 단계 이동 버튼, 원형 큐 체험, 자동 복사와 완료 체크 저장에는 JavaScript가 필요합니다.</p>": "<p class=\"noscript\">The text and complete code remain readable. All diagram steps appear in order. Step controls, the circular queue exercise, automatic copying, and saved completion checks require JavaScript.</p>",
